style.css:
@-moz-document url-prefix("https://www.youtube.com") {
.html5-play-progress, .ytp-play-progress {
   background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAAMCAYAAACji9dXAAAAAXNSR0IArs4c6QAAAEBJREFUGFdjKJh18T/Djo///zPwrP7wn0Fs0Yf/DLKzPvxnUJ/86T+DfufH/wwWTZ//MzhUfvrP4Fn4CaoYpA0A9g0iSuXYdNoAAAAASUVORK5CYII=") repeat-x !important; 
background: linear-gradient(#FF0000) !important;
background: -webkit-linear-gradient(#FF0000) !important;
background: -moz-linear-gradient(left, #FF0000 0%, #FF0000 16.5%, #FF9900 16.5%, #FF9900 33%, #FFFF00 33%, #FFFF00 50%, #33FF00 50%, #33FF00 66%, #0099FF 66%, #0099FF 83.5%, #6633ff 83.5%, #6633ff 100%) !important;
}

.html5-load-progress, .ytp-load-progress {
   background:  url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAAMCAYAAACji9dXAAAAAXNSR0IArs4c6QAAADpJREFUGFcty6ENAEEIRcFXMwJBgiJBrFhHi7TxN5ecn2FmxO6Ke68454juFlUlMlNEhHB3YWY//toD2+cg1+zFeL4AAAAASUVORK5CYII=") !important;
}

.html5-scrubber-button, .ytp-scrubber-button {
   background: url("data:image/png;base64,") !important;
   width: 16px !important;
   height: 16px !important;
    image-rendering: pixelated;

   border: none !important;
   margin-left: 0px !important;
   margin-top: 2px !important;
-webkit-transform: scale(0.0);
}
.ytp-progress-bar-container:hover .ytp-scrubber-button,
.ytp-progress-bar-container:hover .ytp-load-progress{}
.html5-progress-bar-container, .ytp-progress-bar-container {
   height: 12px !important;
}
.html5-progress-bar, .ytp-progress-bar {
   margin-top: 12px !important;
}
.html5-progress-list, .ytp-progress-list, .video-ads .html5-progress-list.html5-ad-progress-list, .video-ads .ytp-progress-list.ytp-ad-progress-list {
   height: 12px !important;
}
.ytp-volume-slider-track {
   background: #0000ff !important;
}


/* Logo */

#logo-icon
  {
    content: url("data:image/gif;base64,") !important;
    width: 123px;
    height: 32px;
    object-fit: fill;
      image-rendering: pixelated;

  }

  ytd-topbar-logo-renderer
  {
    width: 0%;
  }


